{
  "skill": "running-ceridwen-experiments"
}

{
  "command": "cd \"$PWD\"; ls -t results/ | head -20; grep -ril noll results/*/experiment.json 2>/dev/null | head",
  "description": "List recent results and find Noll experiment configs"
}

{
  "command": "grep -ril noll results/ --include=*.json -l 2>/dev/null | head -20; echo ---; grep -rli noll notebooks/ceridwen_integrated_photometry_spectra.ipynb scripts/*.py wiki/research/direction.md 2>/dev/null; echo; git log --oneline -15 --all | cat",
  "description": "Find files mentioning Noll"
}

{
  "command": "python3 scripts/ceridwen_state.py 2>&1 | head -150",
  "description": "Print Ceridwen settings and priors state"
}

{
  "command": "bd list --status open,in_progress --json 2>&1 | head -20; sed -n 1,60p scripts/ceridwen_state.py",
  "description": "Check bd error and state script header"
}

{
  "command": "ceridwen/.venv/bin/python - <<'EOF'
import json
nb=json.load(open("notebooks/ceridwen_integrated_photometry_spectra.ipynb"))
for i,c in enumerate(nb["cells"]):
    s="".join(c["source"])
    if "PRIORS = {" in s or "SETTINGS = {" in s:
        print(i); print(s[:6000])
EOF",
  "description": "Print SETTINGS and PRIORS from production notebook"
}

{
  "command": "for d in results/m1-210210-*; do echo \"== $d\"; ls $d; cat $d/experiment.json 2>/dev/null; done 2>&1 | head -120; git show --stat 48f56a4 | head -30",
  "description": "Inspect M1_210210 result dirs and configs"
}

{
  "command": "git show --stat --name-only 48f56a4 | grep -E \"experiment.json|result.h5\"; cat results/m1-210210-neb-eline-ca-nohe-2026-09-30/experiment.json; ls results/m1-210210-neb-eline-ca-nohe-2026-09-30/run/fits/*/",
  "description": "Locate the production-default zevo fit"
}

{
  "command": "ls wiki/research/experiments/ | head -50; grep -il noll wiki/research/experiments/*.md wiki/notes/*.md 2>/dev/null | head",
  "description": "List research records mentioning Noll"
}

