{
  "command": "cat wiki/research/experiments/e-dust-bump.md | head -120",
  "description": "Read dust-bump research record"
}

{
  "command": "cat results/m1-210210-neb-eline-ca-nohe-zevo-2026-09-30/experiment.json; for f in e-quiescent-speedups e-six-target-new-defaults e-zevo; do echo \"== $f\"; sed -n 1,20p wiki/research/experiments/$f.md; done",
  "description": "Read zevo config and recent records"
}

{
  "command": "ls results/quiescent-test-set-speedups-2026-10-01/; cat results/quiescent-test-set-speedups-2026-10-01/experiment.json 2>/dev/null | head -40; ls results/quiescent-test-set-speedups-2026-10-01/run/fits/*/ 2>/dev/null",
  "description": "Inspect ten-galaxy speedups results"
}

{
  "command": "ceridwen/.venv/bin/python - <<'EOF'
import h5py, numpy as np, glob
from scipy.special import softmax
for d in sorted(glob.glob("results/m1-210210-kcbump*/run*/fits/*/210210-M1_210210"))+sorted(glob.glob("results/m1-210210-neb-eline-ca-nohe-2026-09-30/run/fits/*/210210-M1_210210")):
    try: f=h5py.File(d+"/ceridwen_result.h5")
    except Exception as e: print(d, e); continue
    w=softmax(f["samples/log_weights"][:]); print("==",d)
    for n in ["diffuse_tau_noll","diffuse_delta","diffuse_Ebump","dust_ratio","zh_beta_unit"]:
        if "samples/"+n not in f: continue
        x=f["samples/"+n][:]; o=np.argsort(x); c=np.cumsum(w[o])
        print(f"{n:18s}", " ".join(f"{x[o][np.searchsorted(c,p)]:8.3f}" for p in (0.025,0.16,0.5,0.84,0.975)))
EOF",
  "description": "Posterior quantiles for earlier Noll-law M1_210210 fits"
}

{
  "command": "cd ceridwen && grep -n \"def mass_mapped_beta\" -A40 $(grep -rl \"def mass_mapped_beta\" --include=*.py . | grep -v .venv | head -1); grep -n \"zh_beta_unit\" -r ../notebooks/ceridwen_integrated_photometry_spectra.ipynb | head; grep -n \"diffuse_delta\\|diffuse_Ebump\" ../wiki/notes/model.md | head",
  "description": "Inspect beta mapping and zevo prior usage"
}

{
  "command": "cd \"/Users/liuhao/Downloads/Astro project/tmp/agent-hillclimb/sandboxes_r2/effort-high/slot0\"; grep -rn \"def mass_mapped_beta\" -A25 ceridwen/src ceridwen/ceridwen 2>/dev/null | head -40; python3 -c \"import json;m=json.load(open('results/quiescent-test-set-speedups-2026-10-01/run/manifest.json'));print({k:m[k] for k in m if k not in ('attempts',)}.keys()); print(m.get('config') or m.get('experiment'))\" | head -30",
  "description": "Inspect beta mapping and speedups run config"
}

{
  "command": "mkdir -p results/m1-210210-noll-wide-2026-10-12 && cat > results/m1-210210-noll-wide-2026-10-12/experiment.json <<'EOF'
{
  "targets": [
    "M1_210210"
  ],
  "seed": 20260927,
  "settings": {},
  "priors": {
    "diffuse_delta": "Uniform(low=-3.0, high=0.4)",
    "diffuse_Ebump": "Uniform(low=0.0, high=20.0)"
  },
  "arms": {
    "noll_wide": {}
  }
}
EOF
python3 scripts/experiment.py run results/m1-210210-noll-wide-2026-10-12/experiment.json --gpu "RTX 5090" --output results/m1-210210-noll-wide-2026-10-12/run --dry-run 2>&1 | tail -40",
  "description": "Write wide-prior config and dry-run it"
}

{
  "command": "python3 scripts/experiment.py run results/m1-210210-noll-wide-2026-10-12/experiment.json --gpu \"RTX 5090\" --output results/m1-210210-noll-wide-2026-10-12/run --dry-run > $TMPDIR/dry.txt 2>&1; echo exit=$?; head -60 $TMPDIR/dry.txt; grep -in \"warn\\|error\\|missing\" $TMPDIR/dry.txt; ls results/m1-210210-noll-wide-2026-10-12; git status --short",
  "description": "Recheck dry-run exit code and settings section"
}

{
  "command": "git -C ceridwen status --short | head",
  "description": "Check what changed inside the ceridwen submodule"
}

{
  "command": "stat -f \"%Sm\" ceridwen/tests/fixtures/ssp_data_bpass_agb_dust.h5; date",
  "description": "Check fixture modification time"
}

{
  "command": "git add results/m1-210210-noll-wide-2026-10-12/experiment.json && git commit -q -m \"M1_210210 noll_wide config: diffuse_delta Uniform(-3, 0.4), diffuse_Ebump Uniform(0, 20) on production defaults\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\" && git log --oneline -1 && git push 2>&1 | tail -3",
  "description": "Commit the experiment config and try to push"
}
